  "settings.themeVars": "Colores del tema",
  "settings.themeVars.help": "Recolorea el tema activo variable a variable —superficies, texto, bordes, el acento, colores de estado— en una ventana propia, junto con el estilo de las esquinas. Las anulaciones se aplican en todos los temas, no solo en este.",
  "settings.themeVars.open": "Personalizar…",
  "theme.title": "Colores del tema",
  "theme.intro": "Cada valor de aquí anula el token del tema activo —en este tema y en todos los demás— hasta que lo restablezcas. Los colores son #rrggbb, o #rrggbbaa cuando un valor debe seguir siendo translúcido.",
  "theme.reset": "Restablecer todo",
  "theme.resetOne": "Volver al valor del tema",
  "theme.overridden": "{n} anulados",
  "theme.none": "Nada anulado",
  "theme.presets": "Temas guardados",
  "theme.presets.help":
    "Guarda el aspecto completo con un nombre — tema base, acento, cada color que hayas cambiado aquí y el estilo de esquinas — para volver a él más tarde o mantener dos paletas en paralelo.",
  "theme.presets.name": "Nombra este aspecto",
  "theme.presets.save": "Guardar el actual",
  "theme.presets.replace": "Sustituye al tema guardado con el mismo nombre",
  "theme.presets.full": "La lista está llena — {n} temas guardados. Borra uno primero.",
  "theme.presets.none": "Aún no hay nada guardado. Nombra el aspecto actual y aparecerá aquí.",
  "theme.presets.load": "Cargar",
  "theme.presets.loadHelp": "Aplicar este aspecto — tema base, acento, colores y esquinas",
  "theme.presets.update": "Sobrescribir con el aspecto actual",
  "theme.presets.delete": "Eliminar",
  "theme.presets.confirm": "¿Eliminar?",
  "theme.presets.meta": "{theme} · {n} colores",
  "theme.presets.metaPlain": "{theme} · colores del tema sin cambios",
  "theme.palette": "Colores de este tema",
  "theme.palette.pick": "Elige entre los colores que este tema ya usa",
  "theme.group.surfaces": "Superficies",
  "theme.group.surfaces.help": "La ventana, sus paneles y las cabeceras que van encima: las barras de pestañas de las subventanas y las cabeceras del panel de archivos, que comparten una segunda superficie. La barra superior de la app sigue a --bg-header desde aquí hasta que le des un relleno propio en «Barra superior», más abajo.",
  "theme.group.topframe": "Barra superior",
  "theme.group.topframe.help": "La barra de título de {app}: la franja que lleva el reloj, las pastillas de proyecto y los botones de ventana. La forman tres capas: un relleno, un velo de acento sobre él y la costura de debajo, que dice dónde acaba el cromo de la app y empieza su contenido. Cada una sigue a un token compartido hasta que la fijes, así que la barra se puede retonar sin que el acento se mueva por el resto de la ventana. Los tres niveles de texto de abajo se reasignan para todo el subárbol de la barra, así que un valor mueve a la vez todas sus etiquetas; los menús que se despliegan desde la barra conservan la tinta del tema.",
  "theme.group.subwindow": "Subventanas",
  "theme.group.subwindow.help": "La cabecera propia de una subventana —la barra de pestañas sobre cada panel— más las dos marcas que dicen qué subventana tiene el foco. La barra comparte la segunda superficie de cromo de la app con todas las cabeceras del panel de archivos, y sus marcas leen el acento pelado, así que nada de esto se podía mover por separado. Fija aquí un nivel de texto y la barra entera lo sigue: etiquetas de pestaña, asa, flechas, distintivos.",
  "theme.group.sidepanel": "Panel lateral",
  "theme.group.sidepanel.help": "El panel de archivos que entra desde el borde, por su cuenta. Cada valor de aquí sigue al token compartido que leería en otro caso, así que el panel solo se separa del resto de la ventana cuando fijas uno — y sus cabeceras se mueven sin arrastrar las barras de pestañas de las subventanas.",
  "theme.group.alerts": "Tira de alertas",
  "theme.group.alerts.help": "El grupo de alertas bajo el árbol de archivos: correo urgente, las próximas citas, las tarjetas que vencen. Su aspecto se deriva del acento, del fondo de la ventana y de los colores de estado; estos valores son esa derivación, así que la tira se puede retonar sin mover aquello de lo que toma prestado.",
  "theme.group.text": "Texto",
  "theme.group.text.help": "Los tres niveles de texto, del más claro al más apagado.",
  "theme.group.borders": "Bordes",
  "theme.group.borders.help": "Separadores y contornos: el visible y el susurro.",
  "theme.group.accent": "Acento",
  "theme.group.accent.help": "El tono propio del tema y sus estados. El acento en sí es un ajuste propio común a todos los temas: elige un preajuste o cualquier otro color, y el resto se deriva de él hasta que se fija aquí.",
  "theme.group.controls": "Controles",
  "theme.group.controls.help": "Campos y botones, más los velos neutros de hover e incrustación que se posan sobre cualquier superficie.",
  "theme.group.status": "Estado",
