  "mcpSecurity.family.projects": "Resúmenes de proyectos",
  "mcpSecurity.family.mail": "Herramientas de correo",
  "mcpSecurity.agent": "Agente raíz",
  "mcpSecurity.local_model": "Modelo local",
  "mcpSecurity.reader": "Lector de correo",
  "mcpSecurity.audit": "Actividad MCP reciente",
  "mcpSecurity.auditHelp": "Los últimos 50 de hasta 500 registros en memoria durante esta ejecución. Los registros incluyen sesión, herramienta, decisión, tiempos y una categoría fija de motivo (en sesiones de programación también el destino), sin credenciales, argumentos ni cuerpos de mensajes. Las solicitudes rechazadas antes de autenticarse aparecen como «Sin sesión», con su propio límite. Un registro pertenece al token de la pestaña: todo lo que el agente ejecute en esa pestaña (un hook, un script, una compilación) hereda el token y puede llamar a las herramientas como esa pestaña, así que un registro es de la pestaña, no necesariamente una llamada del propio agente.",
  "mcpSecurity.time": "Hora",
  "mcpSecurity.caller": "Sesión",
