  "mobile.title": "{app} Mobile",
  "mobile.mailWrites": "Correo desde el teléfono",
  "mobile.mailRead": "Leer el correo en el teléfono",
  "mobile.mailReadHelp": "Un teléfono emparejado puede listar tus cuentas y carpetas de correo y abrir mensajes. Desactivado, la vista de correo del teléfono se rechaza por completo, incluidos marcar y responder.",
  "mobile.mailActions": "Marcar como leído y destacar desde el teléfono",
  "mobile.mailActionsHelp": "Un teléfono emparejado puede marcar un mensaje como leído o no leído y poner o quitar su estrella. El escritorio aplica la marca a través de su propia sesión de correo y responde con la lista actualizada. Eliminar y mover se quedan en el escritorio, donde se pueden deshacer.",
  "mobile.mailReply": "Responder desde el teléfono",
  "mobile.mailReplyHelp": "Un teléfono emparejado puede enviar una respuesta en texto plano a un mensaje que esté leyendo. El teléfono solo aporta el texto: el destinatario, el asunto y el hilo salen del mensaje original, de modo que un teléfono solo puede responder a quienes ya te escribieron. Sin correos nuevos, sin adjuntos, sin firma ni cifrado. Un teléfono perdido con esto activado puede enviar correo en tu nombre hasta que lo revoques.",
  "mobile.settingsHelp": "Acceso privado a los terminales de proyecto a través de Tailscale Serve. El host escucha solo en loopback y cada navegador debe emparejarse. Funciona mientras {app} funciona: se inicia con la aplicación y se detiene al cerrarla.",
  "mobile.healthOffTitle": "Mobile está apagado",
  "mobile.healthOffDetail": "Actualmente no hay ningún host de {app} Mobile publicado.",
  "mobile.healthStoppedTitle": "El host está detenido",
  "mobile.healthStoppedDetail": "Mobile está activado en los ajustes pero no está sirviendo; inícialo solo después de comprobar el mapeo privado de Serve.",
  "mobile.healthServeTitle": "El mapeo de Serve necesita atención",
  "mobile.healthServeDetail": "{app} no puede verificar actualmente su mapeo HTTPS privado exacto de loopback.",
  "mobile.healthGoodTitle": "Publicación privada verificada",
  "mobile.healthGoodDetail": "El host es solo loopback y la ruta configurada de Tailscale Serve es HTTPS privado.",
  "mobile.lockdownNow": "Bloquear ahora",
  "mobile.lockdownTitle": "Revocar todos los dispositivos emparejados y detener el host",
  "mobile.lockdownTitleStopped": "El host ya está detenido",
  "mobile.lockdownConfirm": "¿Bloquear {app} Mobile ahora? Esto revoca inmediatamente todos los teléfonos emparejados, cierra sus conexiones de terminal y detiene el host de Mobile. Cada teléfono tendrá que emparejarse de nuevo.",
  "mobile.lockdownPartial": "El bloqueo solo se completó parcialmente: {reason}",
  "mobile.scopeHelp": "Esto comprueba la forma de publicación de {app}, no tus ACL del tailnet, la MFA de la cuenta, Tailnet Lock ni el bloqueo de pantalla del teléfono. Configura esos en Tailscale y en el teléfono.",
  "mobile.phoneInstallTitle": "Instalar {app} Mobile en tu teléfono",
  "mobile.phoneInstallHelp": "Verifica el mapeo privado de Tailscale Serve y luego muestra la URL de confianza y un código QR escaneable en un terminal raíz. No activa Mobile ni cambia tu configuración de Tailscale.",
  "mobile.phoneInstallButton": "Mostrar QR de instalación",
  "mobile.phoneInstallTab": "Instalar {app} Mobile en el teléfono",
  "mobile.phoneInstallToast": "La entrega de instalación al teléfono se está ejecutando en el terminal raíz",
  "mobile.phoneInstallError": "No se pudo abrir la entrega de instalación al teléfono: {reason}",
  "mobile.guideSummary": "Configurar Tailscale Serve",
  "mobile.windowsTerminalsNote": "En Windows, el teléfono no puede abrir los terminales ni las pestañas de agentes de este equipo: se conectan a través de tmux, que Windows no tiene.",
  "mobile.guideIntro": "Haz esto en este ordenador antes de activar {app} Mobile. Instala Tailscale e inicia sesión aquí; luego instálalo e inicia sesión en el mismo tailnet en el teléfono o tableta que usará Mobile.",
  "mobile.guideStep1a": "En un terminal de este ordenador, inspecciona su publicación existente con",
  "mobile.guideStep1b": ". {app} Mobile necesita el manejador HTTPS / (raíz), así que no sustituyas un manejador raíz existente salvo que quieras mover ese servicio.",
  "mobile.guideStep2a": "Configura el proxy inverso privado y persistente. Usa Serve, no Funnel:",
  "mobile.guideStep2b": "Si Tailscale pide aprobación o configurar HTTPS, complétalo en el navegador que abre.",
  "mobile.guideStep3a": "Ejecuta",
  "mobile.guideStep3b": "de nuevo y luego usa",
  "mobile.guideStep3c": "más abajo. {app} rellena el nombre del ordenador, el puerto loopback y el origen verificado a partir del mapeo raíz privado.",
  "mobile.guideStep4a": "Activa {app} Mobile. {app} verifica que el manejador raíz del origen redirige exactamente a",
  "mobile.guideStep4b": "; usa",
  "mobile.guideStep4c": "si cambiaste Tailscale en otro terminal.",
  "mobile.guideStep5": "Activa los proyectos locales que quieras exponer, crea un código de emparejamiento y luego abre el origen verificado en el teléfono o tableta e introduce ese código.",
  "mobile.guideOutro": "La dirección solo es accesible para los dispositivos permitidos en tu tailnet, y Mobile sigue exigiendo su propio emparejamiento de dispositivos. No uses Tailscale Funnel: hace público el servicio y {app} se negará a iniciarse.",
  "mobile.setUpInTerminal": "Configurar en el terminal",
  "mobile.setUpInTerminalHelp": "Abre un terminal raíz y ejecuta el comando de arriba tras confirmar.",
  "mobile.setUpConfirm": "Esto abrirá un terminal raíz y ejecutará:\n\n{command}\n\nActualiza el manejador raíz HTTPS de Tailscale Serve y puede sustituir un servicio montado actualmente en /. ¿Continuar?",
