  "mobile.tunnel.step.forceStop": "¿Ya está conectado? Fuerza su detención: Ajustes → Aplicaciones → Tailscale → Forzar detención, y vuelve a abrirlo. Tras un cambio de red puede decir que está conectado sin transmitir nada; apagarlo y encenderlo no lo arregla.",
