  "mobile.indDeviceAccessHint": "Elegir qué secciones y proyectos ve {name}",
  "mobile.setupIntro": "{app} Mobile lleva los proyectos, terminales y agentes de este ordenador a tu teléfono. Viaja por tu propia red privada de Tailscale: no se publica nada en internet y el teléfono todavía debe emparejarse.",
  "mobile.setupStep1Title": "Instalar Tailscale en este ordenador",
  "mobile.setupStep1Body": "Instala Tailscale aquí e inicia sesión. Es lo que transporta la conexión del teléfono: {app} solo escucha en loopback.",
  "mobile.setupStep2Title": "Instalar Tailscale en el teléfono",
  "mobile.setupStep2Body": "Instala la app de Tailscale en el teléfono o la tableta e inicia sesión en la misma tailnet que este ordenador.",
  "mobile.setupStep3Title": "Publicar {app} de forma privada",
  "mobile.setupStep3Body": "Apunta Tailscale Serve al puerto loopback de {app}. Usa Serve, nunca Funnel: Funnel lo haría público y {app} se negaría a arrancar. Si Tailscale pide aprobación o configurar HTTPS, complétalo en el navegador que abra.",
  "mobile.setupStep4Title": "Activar {app} Mobile",
  "mobile.setupStep4Body": "En Ajustes → Móvil pulsa «Detectar los ajustes de Tailscale Serve», revisa el nombre del ordenador, el puerto y el origen que rellena, y activa {app} Mobile. {app} verifica la asignación antes de iniciar el host.",
  "mobile.setupStep5Title": "Elegir qué puede abrir el teléfono",
  "mobile.setupStep5Body": "En «Acceso por proyecto», dentro de esos mismos ajustes, activa los proyectos y las cajas que el teléfono puede abrir. Todo está desactivado hasta que lo actives.",
  "mobile.setupStep6Title": "Emparejar el teléfono",
  "mobile.setupStep6Body": "Pulsa «Mostrar QR de instalación» y escanéalo con el teléfono, luego crea un código de emparejamiento e introdúcelo allí. Un código es válido cinco minutos.",
  "mobile.setupOpenSettings": "Abrir los ajustes de Mobile",
  "settings.usageStats": "Estadísticas de uso",
  "settings.pdfMarkup": "Marcado de PDF",
  "settings.pdfMarkupHelp": "Lo que Marcar del visor de PDF envía al agente. Se guarda en este ordenador; el teléfono tiene el suyo (Inicio → Este teléfono → Prompt de marcado).",
  "settings.pdfMarkupInstruction": "Prompt de marcado",
  "settings.pdfMarkupInstructionHelp": "Va tras el archivo, la copia marcada, las capas y tus notas en cada envío. Con «Aplicar las marcas directamente» activado, por defecto el agente hace los cambios y recompila el PDF; si no — o donde no se puede guardar un deshacer — le pide que liste los cambios y no edite nada hasta que se lo digas.",
  "settings.pdfMarkupApply": "Prompt de «Aplicar estos cambios»",
  "settings.pdfMarkupApplyHelp": "Lo envía el botón Aplicar estos cambios cuando el agente ha listado lo que piden tus marcas.",
  "settings.pdfMarkupAutoReload": "Recargar el PDF bajo tus marcas cuando cambie",
  "settings.pdfMarkupAutoReloadHelp": "Cuando el agente recompila un PDF que estás marcando, sus páginas nuevas aparecen solas bajo tus marcas. Desactivado: la barra de marcas ofrece Recargar PDF.",
  "settings.pdfMarkupSubagents": "Pasar cada envío a un subagente nuevo",
  "settings.pdfMarkupSubagentsHelp": "Cada envío pide al agente que pase la ronda a un subagente nuevo propio y quede libre al instante, así la siguiente ronda sale sin esperar — las rondas avanzan en paralelo. Para agentes que pueden lanzar subagentes (Claude Code); uno que no puede hace la ronda él mismo.",
  "settings.pdfMarkupDirect": "Aplicar las marcas directamente",
  "settings.pdfMarkupDirectHelp": "Al enviar, el agente hace los cambios de inmediato; cuando termina, Deshacer devuelve cada archivo que la ronda cambió — y se niega antes que sobrescribir lo que cambió desde entonces. Donde no se puede guardar un deshacer (no es un repositorio git, demasiados archivos sin seguimiento, …), o con esto desactivado, el agente lista los cambios primero y «Aplicar estos cambios» hace que los haga.",
  "settings.pdfMarkupReset": "Usar el predeterminado",
  "markup.ask.label": "Preguntas sobre tus marcas",
  "markup.ask.help": "Con qué frecuencia el agente te pregunta por una marca antes de listar los cambios. Se añade tras el prompt de marcado en cada envío.",
  "markup.ask.stop0": "Preguntar siempre",
  "markup.ask.stop1": "Preguntar a menudo",
  "markup.ask.stop2": "Preguntar si hay duda",
  "markup.ask.stop3": "Preguntar poco",
  "markup.ask.stop4": "No preguntar nunca",
  "markup.ask.hint0": "Una pregunta por cada marca antes de contarla como cambio.",
  "markup.ask.hint1": "Pregunta en cuanto una marca deja alguna opción.",
  "markup.ask.hint2": "Pregunta solo por marcas ilegibles u opciones reales; en lo demás toma la lectura obvia.",
  "markup.ask.hint3": "Pregunta solo si no puede actuar sobre una marca sin tu respuesta.",
  "markup.ask.hint4": "Decide cada marca dudosa por sí mismo y lista lo que decidió.",
  "settings.dailyRecap": "Mostrar el resumen al inicio de cada día",
  "settings.openUsageStats": "Abrir estadísticas de uso",

