  "shortcuts.resetAll": "Restablecer todo a los valores predeterminados",
  "shortcuts.resetAllTitle": "Eliminar todos los atajos personalizados",
  "shortcuts.conflict": "También asignado a: {actions}",
  "shortcuts.help": "Haz clic en un atajo y pulsa la nueva combinación de teclas; × lo desactiva. En Linux, alternar paneles también admite una pulsación sola de Super.",
  "shortcuts.unbind": "Desactivar",
