  "shortcuts.steeringHelp": "Las teclas a las que responde la navegación de {app} una vez que {chord} la activa. Cada acción admite hasta dos teclas, sin modificadores; una letra puede significar una cosa en el nivel de proyectos y otra dentro de una subventana.",

