  "steering.newAgent.label": "Nueva pestaña de agente",

  "steering.newAgent.desc": "Una nueva pestaña de agente en la subventana enfocada: 1 es el agente predeterminado, 2–9 los demás del menú + en su orden (la leyenda muestra cuántos). La navegación de {app} sigue activa.",
