  "steering.agentClear.label": "Borrar conversación",
  "steering.agentClear.desc": "Escribe /clear en la pestaña de agente activa: una conversación nueva, que «Deshacer borrado» en la pestaña recupera. La navegación de {app} sigue activa.",
  "steering.agentPlan.label": "Plan",
