  "steering.agentGoal.label": "Objetivo",
  "steering.agentGoal.desc": "Abre el cuadro de prompt con /goal al principio de la entrada de la pestaña de agente activa; escribe el resto, pulsa Intro y vuelve la navegación de {app}.",
  "steering.agentPrompt.label": "Prompt",
  "steering.agentPrompt.desc": "Abre un cuadro de texto en el centro de la ventana para la pestaña de agente activa. Intro lo envía (sustituye cualquier borrador en la entrada del agente) y vuelve la navegación de {app}; Esc vuelve sin enviar.",
