  "steering.jumpProject.label": "Ir a proyecto",
  "steering.jumpProject.desc": "Escribir el nombre de un proyecto abierto o inactivo y pulsar Intro para cambiar a él; uno inactivo se activa. Después vuelve la navegación de {app}.",
  "steering.popout.label": "Ventana separada",
  "steering.popout.desc": "Trae al frente la subventana separada de este proyecto para trabajar en ella; con varias, cada pulsación pasa a la siguiente. La navegación de {app} termina cuando la ventana toma el teclado.",
  "steering.exit.label": "Salir",
