  "steering.legend.label": "Ocultar teclas",
  "steering.legend.desc": "Pliega esta lista de teclas en un botón redondo abajo en el centro; la navegación de {app} sigue activa. La misma tecla (o un clic en el botón) la vuelve a mostrar.",
