  "agentCron.title": "Calentamiento programado",
  "agentCron.help":
    "A cada hora indicada abajo, {app} envía un único mensaje «{message}» a ese agente en segundo plano — en el modo de una sola ejecución de la propia CLI (claude -p, codex exec, …), sin terminal, pestaña ni proyecto. La cuota de una CLI de agente es una ventana que se abre con tu primer mensaje —la de Claude dura cinco horas—, así que esto decide cuándo empieza la ventana en vez de dejarlo al primer prompt real que escribas.",
  "agentCron.runningNote":
    "Solo se dispara mientras {app} está en marcha. Una hora que pasa con la app cerrada, o con la máquina suspendida, se omite ese día y nunca se envía tarde: enviarla horas después abriría la ventana en el peor momento posible.",
