  "agentSchedule.warning": "Cuando vence un prompt, {app} espera hasta una hora a que haya un punto seguro de inactividad. La entrega sustituye cualquier texto sin enviar del editor del agente, incluso si la pestaña tiene el foco.",
  "agentSchedule.openOnly": "La entrega corre a cargo del {app} que esté activo: una ventana abierta o, con {app} Mobile activado, su servicio en segundo plano mientras no haya ninguna ventana abierta, que antes reinicia la sesión de este agente si se ha detenido. Las ocasiones perdidas se registran y los programas recurrentes nunca envían de golpe un atraso.",
