  "howToStart.title": "Bienvenido a {app}",
  "howToStart.intro": "{app} mantiene tu desarrollo asistido por IA en una sola ventana. Así es como empezar:",
  "howToStart.openFeatureGuide": "Abrir guía de funciones...",
