  "pill.containerScopeAgentsHelp": "Los shells, los scripts y Ejecutar/Depurar se quedan en el host, con tu cadena de herramientas del host — un entorno .venv, conda o pyenv vuelve a funcionar, porque su intérprete vive en el host y no en la imagen.",
  "pill.containerScopeAgentsCaveat": "El agente sigue escribiendo en la carpeta del proyecto, así que un script suyo está a un clic de Ejecutar de todo tu equipo. No puede dar ese paso por sí solo — ningún archivo del proyecto se relee como algo que lanzar — pero lee lo que ejecutas. Para código que esperas hostil y no solo sin revisar, un contenedor es el nivel equivocado.",
