  "pill.vmRebuildTitle": "¿Reconstruir esta VM?",
  "pill.vmRebuildConfirm": "Esto recrea el disco de la VM desde la imagen base. Todo lo que hay dentro muere con él — para un proyecto sin espejo, el disco de la VM ES el árbol de trabajo; solo sobrevive lo enviado a un remoto git (o descargado). ¿Continuar?",
  "pill.vmNumbersError": "Memoria, CPU y disco deben ser enteros positivos",
  "pill.vmMemory": "Memoria (MiB)",
  "pill.vmCpus": "CPU",
  "pill.vmDisk": "Disco (GiB, virtual)",
