  "pill.vmEgress": "Salida de red",
  "pill.vmEgressProxy": "Solo API de agentes (proxy con lista de permitidos)",
  "pill.vmEgressOff": "Ninguna (totalmente cerrada)",
  "pill.vmEgressOpen": "Abierta (red completa)",
  "pill.vmEgressProxyCaveat": "La VM solo alcanza los hosts de abajo a través del proxy de {app}; todo lo demás se bloquea y registra. Límite honesto: un agente aún puede enviar datos a los puntos permitidos (p. ej., dentro de un prompt) — el proxy estrecha el canal, no puede cerrarlo. Los cambios de modo se aplican en el próximo arranque.",
  "pill.vmEgressOffNote": "Sin salida de red la VM no alcanza nada — las pestañas de agentes en la nube no funcionan; use un modelo local o aislamiento puro de build/test.",
  "pill.vmMailReader": "Lector de correo",
  "pill.vmMailReaderHelp": "Las pestañas de agente de esta VM pueden leer las cuentas de correo que haya abierto a los agentes y escribir borradores. Su salida está acotada y registrada, no sellada: el agente sigue alcanzando a su propio proveedor, que recibe lo que lee. Nunca puede enviar — solo sale un borrador que envíe usted. Se aplica desde el próximo arranque; sin espejo, y los archivos que descargue de esta VM pueden contener correo.",
  "pill.vmMailReaderWide": "Un lector de correo solo funciona con salida Proxy y la lista de permitidos predeterminada — sin GitHub ni hosts adicionales. Desactive «Lector de correo» para ampliar la red.",
  "pill.vmAllowGithub": "Permitir github.com (clonar/push)",
  "pill.vmAllowHosts": "Hosts adicionales permitidos (uno por línea)",
  "pill.vmAllowHostsPlaceholder": "registry.npmjs.org\n.crates.io",
  "pill.vmBlockedCount": "{count} conexión(es) bloqueada(s) — la VM intentó alcanzar hosts fuera de la lista:",
  "pill.pythonInterpMenuTitle": "El entorno Python en el que se ejecutan y depuran los scripts de este proyecto. Detectado automáticamente por defecto (venv en el árbol, poetry, conda, pyenv); fija uno cuando tu entorno esté donde {app} no pueda inferirlo.",
  "pill.pythonInterpreterEllipsis": "Intérprete de Python…",
  "pill.autoConnectTitleNonHeadless": "Conecta este proyecto por sí solo al iniciar y al cambiar a él. {app} no maneja contraseñas en este modo, así que el inicio de sesión (y la VPN, si tiene una) se abre en la terminal raíz para que te autentiques — luego el proyecto se conecta solo.",
  "pill.autoConnectTitleEligible": "Conecta este proyecto por sí solo al iniciar y al cambiar a él. Nunca pide nada: entra directamente cuando el host es accesible, y activa la VPN solo cuando no lo es.",
  "pill.autoConnectTitleNotEligible": "Guarda primero la contraseña SSH (o usa autenticación por clave) — auto-conectar solo se ofrece cuando conectar no necesita nada de ti.",
  "pill.autoConnectOnLaunch": "Conectar automáticamente al iniciar",
  "pill.persistSessionsMenuTitle": "Ejecuta la shell remota y las pestañas de Python/script de este proyecto dentro de una sesión tmux en el host, para que una ejecución larga continúe a través de una caída SSH, la suspensión del portátil o el cierre de {app} — la pestaña se reconecta al volver a conectar. Cerrar una pestaña sigue terminando su sesión (con confirmación). Las pestañas de agente no se ven afectadas.",
  "pill.persistentSessionsTmux": "Sesiones persistentes (tmux)",
  "pill.remoteControlMenuTitle":
    "Si las pestañas de agente Claude de este proyecto pueden supervisarse/dirigirse desde la app o el web de Claude. Haz clic para alternar: usar el ajuste global → forzar desactivado → forzar activado.",
  "pill.remoteControlInherit": "Control remoto (predeterminado)",
  "pill.remoteControlOff": "Control remoto: desactivado",
  "pill.remoteControlOn": "Control remoto: activado",
  "pill.remoteMachinesMenuTitle": "Añade y gestiona máquinas adicionales en las que se ejecuta este proyecto. Ejecutan el mismo código (mantenido en sincronización unidireccional) como trabajadores de experimentos de solo lectura; sus salidas permanecen en cada máquina.",
  "pill.remoteMachinesCount": "Máquinas remotas… ({count})",
  "pill.remoteMachinesEllipsis": "Máquinas remotas…",
  "pill.closeAllTabs": "Cerrar todas las pestañas y ventanas",
  "pill.adoptFolderLayout": "Restaurar el diseño guardado en la carpeta…",
  "pill.adoptFolderLayoutOk": "Se han restaurado {count} pestaña(s) de la carpeta.",
  "pill.adoptFolderLayoutNone": "Esta carpeta no tiene ningún diseño guardado.",
  "pill.dangerZone": "Zona de peligro",
  "pill.detachSshMenuTitle": "Vuelve a convertir esto en un proyecto local. La copia de trabajo local se queda donde está y los archivos del host remoto no se tocan, pero el emparejamiento se elimina: la sincronización Git se detiene y la selección de auto-sincronización que configuraste para este host se descarta.",
  "pill.detachSshEllipsis": "Desconectar host SSH…",
  "pill.removeGitMenuTitle": "Elimina el directorio .git de este proyecto y todo el historial de control de versiones (no se puede deshacer)",
  "pill.removeGitHistoryEllipsis": "Eliminar git e historial…",
  "pill.deleteProjectMenuTitle": "Desconecta este proyecto y muévelo al archivo de {app}. Restáuralo o elimínalo permanentemente más tarde desde Ajustes. Los archivos de un host remoto nunca se tocan.",
  "pill.deleteProjectEllipsis": "Eliminar proyecto…",
  "pill.forgetProjectMenuTitle": "Quita este proyecto de {app} pero deja su carpeta exactamente donde está. No se toca nada dentro de la carpeta: solo desaparecen los registros propios de {app} sobre el proyecto. Después puedes importar la carpeta de nuevo.",
  "pill.forgetProjectEllipsis": "Quitar de {app}…",
  "pill.forgetProjectTitle": "Quitar {name} de {app}",
  "pill.forgetDescPre": "Esto quita",
  "pill.forgetDescMid": "de la lista de proyectos y descarta los registros de {app} sobre él (disposición de pestañas, sesiones, historial de tiempo). Su carpeta",
  "pill.forgetDescPost": "se toca: project.json, los archivos de andamiaje y todo lo demás siguen en el disco, y la carpeta se puede importar de nuevo.",
  "pill.forgetRemoteNote": "El host remoto y el espejo local se quedan como están.",
