  "remoteConnect.autoConnectTitleEligible": "Conecta este proyecto por sí solo al iniciar y al cambiar a él. Nunca pide nada: entra directamente cuando el host es alcanzable, y solo activa la VPN cuando no lo es. Ten en cuenta que activar la VPN redirige todo el tráfico de este equipo — con la auto-conexión eso ocurre sin preguntar, así que vigila el indicador de VPN de la cabecera.",
  "remoteConnect.autoConnectTitleNotEligible": "Primero guarda la contraseña SSH (o usa autenticación por clave) — la auto-conexión solo se ofrece cuando conectar no necesita nada de ti.",
  "remoteConnect.autoConnectLabel": "Auto-conexión",
  "remoteConnect.autoConnectHintEligible": "al iniciar y al cambiar — VPN solo si el host no es alcanzable directamente",
