  "remoteConnect.autoConnectVpnWarningStrong": "sin preguntar",
  "remoteConnect.autoConnectVpnWarningPost": "— redirigiendo el tráfico de este equipo al iniciar. El indicador de VPN de la cabecera muestra cuándo hay un túnel activo, y puede desactivarlo.",
  "remoteConnect.autoConnectInteractiveTitle": "Conecta este proyecto por sí solo al iniciar y al cambiar a él. {app} no maneja contraseñas en este modo, así que el inicio de sesión (y la VPN, si este proyecto tiene una) se abre en la terminal raíz para que te autentiques — el proyecto se conecta por sí solo en cuanto entras.",
