  "remoteConnect.killConfirmTitle": "Confirmar: esto termina todas las sesiones tmux en ejecución en el host — no se puede deshacer.",
  "remoteConnect.killConfirmBtn": "Confirmar: finalizar todos los trabajos",
  "remoteConnect.killArmTitle": "Desconectar activamente: finaliza todos los trabajos tmux en ejecución en este host y cierra la conexión. Los trabajos se terminan solo con este clic — nunca al reiniciar {app}.",
  "remoteConnect.killArmBtn": "Desconectar y finalizar trabajos",
  "remoteConnect.forgetPasswordTitle": "Elimina la contraseña guardada de este host del llavero de tu sistema operativo. La conexión actual sigue activa; la próxima conexión volverá a pedir la contraseña.",
  "remoteConnect.forgetPasswordBtn": "Olvidar contraseña guardada",
  "carefulHost.title": "Mantiene el trabajo en segundo plano de {app} alejado de esta máquina: el censo de tamaño de archivos deja de escanear el host por sí solo, y la monitorización se vuelve más barata y lenta. Úsalo para un nodo de inicio de sesión o cualquier máquina que compartas con otros — no para un nodo de cómputo que ocupas durante la duración de un trabajo, que es tuyo mientras lo tienes.",
  "carefulHost.label": "Tratar esta máquina con cuidado",
  "carefulHost.hintDefault": "para un nodo de inicio de sesión o una máquina compartida: omite los escaneos que leen todo su sistema de archivos",
  "usage.carefulNote":
    "Host HPC — solo se listan tus propias sesiones y procesos. Las normas de uso de un clúster no permiten recopilar nombres o comandos de otros usuarios, así que este informe no se ejecuta automáticamente aquí.",
  "carefulHost.hintOnByDefault": "activado por defecto para cada máquina remota — desactívalo si esta es tuya",
  "carefulHost.hintNotCareful": "esta máquina es tuya: monitorización completa, igual que en local",
