  "remoteMachines.introStrongPrimary": "primaria",
  "remoteMachines.introMid1": "que posee sus archivos y git, además de cualquier máquina worker adicional que ejecuta su",
  "remoteMachines.introStrongSameCode": "mismo código",
  "remoteMachines.introMid2": ". Conecta o gestiona cualquiera de ellas aquí, o añade un nuevo worker más abajo. Un nuevo worker comparte por defecto la carpeta del proyecto de la máquina primaria (sin copia, sin git); marca",
