  "carefulHost.hintHpcTagged": "siempre activo: esta máquina está etiquetada como nodo de inicio de sesión de un clúster HPC",
  "hpcHost.title": "Marca esta máquina como nodo de acceso compartido de un clúster. {app} entonces nunca escanea ni mide su sistema de archivos por su cuenta, no ejecuta sincronización de archivos ni de Git en segundo plano contra ella, nunca se conecta en silencio al arrancar, la lee con moderación diga lo que diga el interruptor de lectura, y pregunta antes de que una ejecución acabe en ella. Nada lo detecta: un planificador en el PATH dice que la máquina tiene SLURM, no que a sus operadores les importe.",
  "hpcHost.label": "Clúster HPC (nodo de inicio de sesión)",
  "hpcHost.hintOn": "trabajo en segundo plano desactivado, lectura ligera forzada, las ejecuciones piden confirmación primero",
  "hpcHost.hintOff": "actívalo para un nodo de inicio de sesión de clúster — nunca para un nodo de cómputo que ocupas durante un trabajo",
