  "machines.hpcToggleTitle": "Marca esta máquina como nodo de acceso compartido de un clúster. {app} entonces la lee con moderación (ni nombres ni comandos de otros usuarios), nunca escanea ni mide su sistema de archivos por su cuenta, nunca ejecuta sincronización de archivos ni de Git en segundo plano contra ella, nunca la comprueba ni se conecta a ella salvo que lo pidas, y pregunta antes de que algo se ejecute en su shell de nodo de acceso. Marcarla también quita su conexión al arrancar.",
  "machines.hpcAddTitle": "Marca esta máquina como nodo de acceso compartido de un clúster. {app} entonces la lee con moderación (nunca nombres ni líneas de comando de otros usuarios), nunca escanea ni mide su sistema de archivos por su cuenta, no ejecuta sincronización de archivos ni de Git en segundo plano contra ella, nunca la comprueba ni se conecta a ella salvo que lo pidas, y pregunta antes de que algo se ejecute en su shell de nodo de acceso.",
