  "deckView.canWriteStarterMsg": "{app} puede escribir un archivo LaTeX inicial junto a ella y compilarlo. El archivo es suyo a partir de entonces — recompilar conserva las capas que añada, que se vuelven a anclar a las diapositivas en las que se colocaron.",
