  "pill.agentFenceGlyphLive": "{count} pestaña(s) de agente de este proyecto se ejecutan fuera del sandbox de agentes: se abrieron antes de que fuera el único modo. Ciérralas y vuelve a abrirlas para meterlas en el sandbox.",
  "pill.agentFenceLiveUnfenced": " · {count} pestaña(s) en marcha fuera del sandbox: ciérralas y vuelve a abrirlas",
  "common.on": "activado",
  "common.off": "desactivado",
  "hpcGuard.duScan.title": "¿Escanear todo el árbol en un clúster?",
  "hpcGuard.duScan.body": "Esto recorre cada archivo bajo la raíz del proyecto para sumar tamaños. En un clúster esa raíz suele estar en el sistema de archivos paralelo, donde un recorrido recursivo supone una petición de metadatos por archivo contra un servidor que comparte todo el centro: justo lo que las guías del sistema de archivos piden no hacer a la ligera. Es un único escaneo, no un bucle, así que puedes lanzarlo si lo quieres.",
  "hpcGuard.duScan.go": "Escanear de todos modos",
  "hpcGuard.census.title": "¿Medir las carpetas del host en un clúster?",
  "hpcGuard.census.body": "El censo de carpetas gigantes ejecuta `du` sobre todo el árbol del host para encontrar lo que es demasiado grande para sincronizar. El mismo coste en metadatos que un escaneo completo, y este normalmente se ejecuta solo al conectar: por eso aquí permanece desactivado salvo que lo pidas.",
  "hpcGuard.census.go": "Medir de todos modos",
  "hpcGuard.connect.title": "¿Iniciar sesión en este clúster?",
  "hpcGuard.connect.body": "Abrir esta pestaña marcaría la máquina y dejaría en ella un maestro SSH compartido (y, para una pestaña persistente, un servidor tmux con él): la presencia desatendida que la etiqueta existe para evitar. Eso es correcto para una pestaña restaurada al reiniciar, que nadie pidió; solo estorba cuando de verdad querías abrir una. Continuar conecta primero el proyecto y luego abre la pestaña.",
  "hpcGuard.connect.go": "Conectar y abrir",
  "hpcGuard.loginNodeRun.title": "¿Ejecutar esto en el nodo de acceso?",
  "hpcGuard.loginNodeRun.body": "Esto se ejecutaría en el nodo de acceso del clúster, compartido con todas las personas conectadas ahora mismo. Los centros piden mantener fuera de él el trabajo intensivo en CPU y se reservan el derecho de matar procesos que lo carguen mucho tiempo. La vía correcta para el mismo trabajo es un trabajo interactivo —el shell srun de la vista Trabajos— o un script por lotes con sbatch.",
  "hpcGuard.loginNodeRun.go": "Ejecutar aquí de todos modos",
  "hpcGuard.note": "Marcaste esta máquina como nodo de acceso de un clúster. Quita la etiqueta en el menú Máquinas si fue un error: aquí no se recuerda nada, así que volverá a preguntar la próxima vez.",
  "unfencedPlatform.title": "Los agentes en este equipo se ejecutan con todos tus permisos",
  "unfencedPlatform.body": "Windows no tiene sandbox de agentes. Un agente iniciado aquí puede leer y cambiar todo lo que puede tu cuenta: otros proyectos, contraseñas guardadas, claves SSH, tu perfil del navegador. En Linux y macOS, {app} mantiene a los agentes en un sandbox limitado a su proyecto; aquí no puede.",
  "unfencedPlatform.alternative": "Acepta para iniciar agentes en este equipo a partir de ahora — {app} pregunta una sola vez. ¿Prefieres un límite? Abre el proyecto en un contenedor.",
  "unfencedPlatform.accept": "Aceptar e iniciar",
  "unfencedPlatform.declined": "No iniciado: los agentes en este equipo se ejecutan con todos tus permisos y eso no se aceptó. Abre una nueva pestaña de agente para que se te pregunte de nuevo, o abre el proyecto en un contenedor.",
  "passwordInput.show": "Mostrar contraseña",
  "passwordInput.hide": "Ocultar contraseña",
