  "rootConsole.mailOpen": "Al menos una cuenta de correo comparte mensajes marcados con agentes que leen correo: un agente lector confinado o, donde los ajustes lo permiten, una pestaña de modelo local. Las pestañas raíz en la nube siguen sin leer correo; solo pueden escribir borradores.",
  "rootConsole.mailOpenAll": "Al menos una cuenta de correo está abierta por completo a un agente lector confinado; una pestaña de modelo local, donde los ajustes lo permiten, sigue viendo solo los mensajes marcados. Las pestañas raíz en la nube siguen sin leer correo; solo pueden escribir borradores.",
